import json
import os
import sys

DATA_FILE = os.path.join(os.path.dirname(os.path.abspath(__file__)), "todos.json")


def load(path=DATA_FILE):
    if not os.path.exists(path):
        return []
    try:
        with open(path, "r", encoding="utf-8") as f:
            data = json.load(f)
    except (json.JSONDecodeError, OSError):
        return []
    if not isinstance(data, list):
        return []
    return data


def save(todos, path=DATA_FILE):
    tmp = path + ".tmp"
    with open(tmp, "w", encoding="utf-8") as f:
        json.dump(todos, f, ensure_ascii=False, indent=2)
    os.replace(tmp, path)


def next_id(todos):
    return max((t["id"] for t in todos), default=0) + 1


def add(text, path=DATA_FILE):
    todos = load(path)
    item = {"id": next_id(todos), "text": text, "done": False}
    todos.append(item)
    save(todos, path)
    return item


def list_todos(path=DATA_FILE):
    return load(path)


def done(item_id, path=DATA_FILE):
    todos = load(path)
    for t in todos:
        if t["id"] == item_id:
            t["done"] = True
            save(todos, path)
            return t
    return None


def remove(item_id, path=DATA_FILE):
    todos = load(path)
    remaining = [t for t in todos if t["id"] != item_id]
    if len(remaining) == len(todos):
        return None
    save(remaining, path)
    return item_id


def parse_id(raw):
    try:
        return int(raw)
    except ValueError:
        raise SystemExit("error: id must be a number, got %r" % raw)


def print_list(todos):
    if not todos:
        print("No todos.")
        return
    for t in todos:
        mark = "x" if t["done"] else " "
        print("[%s] %d. %s" % (mark, t["id"], t["text"]))


def main(argv):
    if not argv:
        print("usage: todo.py add <text> | list | done <id> | remove <id>")
        return 1
    cmd, args = argv[0], argv[1:]

    if cmd == "add":
        if not args:
            raise SystemExit("error: add requires <text>")
        item = add(" ".join(args))
        print("Added #%d: %s" % (item["id"], item["text"]))
    elif cmd == "list":
        print_list(list_todos())
    elif cmd == "done":
        if not args:
            raise SystemExit("error: done requires <id>")
        item_id = parse_id(args[0])
        item = done(item_id)
        if item is None:
            print("No todo with id %d." % item_id)
            return 1
        print("Done #%d: %s" % (item["id"], item["text"]))
    elif cmd == "remove":
        if not args:
            raise SystemExit("error: remove requires <id>")
        item_id = parse_id(args[0])
        if remove(item_id) is None:
            print("No todo with id %d." % item_id)
            return 1
        print("Removed #%d." % item_id)
    else:
        print("unknown command: %s" % cmd)
        print("usage: todo.py add <text> | list | done <id> | remove <id>")
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
